use std::num::ParseIntError;

fn parse_comma_separated_integers(input: &str) -> Result<Vec<i32>, ParseIntError> {
    input
        .split(',')
        .map(|part| part.trim().parse::<i32>())
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn parses_integers() {
        assert_eq!(
            parse_comma_separated_integers("1, 2,-3").unwrap(),
            vec![1, 2, -3]
        );
    }

    #[test]
    fn rejects_non_integer() {
        assert!(parse_comma_separated_integers("1,abc,3").is_err());
    }

    #[test]
    fn empty_string_returns_error() {
        assert!(parse_comma_separated_integers("").is_err());
    }
}
```

`""` 会被拆分为一个空字段，随后 `parse::<i32>()` 失败，因此返回 `Err`。同样，`"1,,3"` 和 `"1,abc,3"` 也会返回错误。
